const cacheJudicialPresidencia=new Map();
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const estiloJudicialPresidencia=document.createElement('style');
estiloJudicialPresidencia.textContent='.presidencia-judicial-resumo{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;border-top:1px solid var(--linha);padding-top:10px}.presidencia-judicial-resumo div{display:grid;gap:2px}.presidencia-judicial-resumo span{font:8px var(--ui);letter-spacing:.1em;color:#948b7d}.presidencia-judicial-resumo b{font:16px var(--serif);font-weight:400}.presidencia-acoes [data-pdf-judicial-presidente]{border:1px solid #d5b58345;padding:8px 9px;font:10px var(--ui);color:#d7c4a5}@media(max-width:700px){.presidencia-judicial-resumo{grid-template-columns:1fr}}';
document.head.append(estiloJudicialPresidencia);
async function carregar(nome){if(cacheJudicialPresidencia.has(nome))return cacheJudicialPresidencia.get(nome);const p=fetch(`/api/observatorio-politico?modo=historico-judicial&nome=${encodeURIComponent(nome)}`).then(async r=>{const d=await r.json();if(!r.ok)throw new Error(d.erro||'Falha');return d});cacheJudicialPresidencia.set(nome,p);return p}
function integrar(){for(const card of document.querySelectorAll('.presidencia-cartao')){const nome=card.querySelector('h4')?.textContent?.trim();if(!nome)continue;if(!card.querySelector('[data-judicial-presidente]')){const bloco=document.createElement('div');bloco.className='presidencia-judicial-resumo';bloco.dataset.judicialPresidente=nome;bloco.innerHTML='<div><span>PROCESSOS PÚBLICOS · STF</span><b>…</b></div><div><span>INQUÉRITOS</span><b>…</b></div><div><span>AÇÕES PENAIS</span><b>…</b></div>';card.querySelector('.presidencia-acoes')?.before(bloco)}const acoes=card.querySelector('.presidencia-acoes');if(acoes&&!acoes.querySelector('[data-pdf-judicial-presidente]')){const b=document.createElement('button');b.dataset.pdfJudicialPresidente=nome;b.textContent='PDF · histórico judicial';acoes.append(b)}}observar()}
let observer=null;function observar(){observer?.disconnect();observer=new IntersectionObserver(es=>{for(const e of es){if(!e.isIntersecting)continue;observer.unobserve(e.target);const nome=e.target.dataset.judicialPresidente;carregar(nome).then(d=>{const r=d.resumo||{};e.target.innerHTML=`<div><span>PROCESSOS PÚBLICOS · STF</span><b>${r.processosPublicosLocalizados??0}</b></div><div><span>INQUÉRITOS</span><b>${r.inqueritos??0}</b></div><div><span>AÇÕES PENAIS</span><b>${r.acoesPenais??0}</b></div>`}).catch(()=>{e.target.innerHTML='<div><span>HISTÓRICO JUDICIAL</span><b>Fonte indisponível</b></div>'})}},{rootMargin:'180px'});document.querySelectorAll('[data-judicial-presidente]').forEach(x=>observer.observe(x))}
function imprimir(nome,d){const r=d.resumo||{},itens=d.dados||[],w=window.open('','_blank','noopener,noreferrer');if(!w)return;w.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Histórico judicial público — ${esc(nome)}</title><style>body{font-family:Arial,sans-serif;margin:36px;color:#111;line-height:1.45}h1,h2{font-family:Georgia,serif}article{padding:12px 0;border-top:1px solid #ccc;break-inside:avoid}small{color:#555}a{color:#111}.contadores{display:flex;gap:24px;flex-wrap:wrap;margin:20px 0}.contadores div{min-width:140px}.contadores b{font-size:26px;display:block}</style></head><body><small>Biblioteca Livre · documento compilado a partir da consulta processual pública do STF</small><h1>${esc(nome)}</h1><p>Investigação, inquérito, ação ou processo não equivalem a condenação. Este arquivo registra resultados públicos localizados pelo nome pesquisado e deve ser conferido nas fontes oficiais.</p><div class="contadores"><div><b>${r.processosPublicosLocalizados??itens.length}</b>processos públicos localizados</div><div><b>${r.inqueritos??0}</b>inquéritos</div><div><b>${r.acoesPenais??0}</b>ações penais</div><div><b>${r.emTramitacao??0}</b>em tramitação</div></div><h2>Registros localizados</h2>${itens.map(x=>`<article><b>${esc(x.classe||'Processo')} ${esc(x.numero)}</b><p>${esc(x.nome||'Registro processual público')} · ${x.tramite?'em tramitação':'fora de tramitação'}</p><a href="${esc(x.url)}">Processo oficial</a> · <a href="${esc(x.inteiroTeor)}">Inteiro teor/acórdãos</a></article>`).join('')||'<p>Nenhum registro foi localizado automaticamente nesta consulta.</p>'}<h2>Limitações</h2><p>${esc(r.cobertura||d.aviso||'')}</p><p>CNJ/DataJud: https://www.cnj.jus.br/sistemas/datajud/api-publica/</p><script>window.onload=()=>setTimeout(()=>window.print(),250)<\/script></body></html>`);w.document.close()}
document.addEventListener('click',async e=>{const b=e.target.closest?.('[data-pdf-judicial-presidente]');if(!b)return;b.disabled=true;const original=b.textContent;b.textContent='Montando…';try{imprimir(b.dataset.pdfJudicialPresidente,await carregar(b.dataset.pdfJudicialPresidente))}finally{b.disabled=false;b.textContent=original}});
integrar();new MutationObserver(integrar).observe(document.body,{childList:true,subtree:true});
